import re
src = open('tests/test_saga.py').read()
lines = src.split('\n')
# find HTTP test classes (those with serve(port=0))
classes = []
cur = None
for i, l in enumerate(lines):
    m = re.match(r'class (\w+)\(', l)
    if m: cur = (m.group(1), i)
    if 'serve(port=0)' in l and cur:
        classes.append(cur)
methods=[]
for cname,start in classes:
    end = len(lines)
    # find next class
    for j in range(start+1,len(lines)):
        if re.match(r'class \w+\(', lines[j]):
            end=j;break
    body=lines[start:end]
    for k,l in enumerate(body):
        m=re.match(r'    def (test_\w+)', l)
        if m:
            methods.append((cname,m.group(1),start+k))
methods.append(('__END__','',len(lines)))
for idx in range(len(methods)-1):
    cname,mname,s=methods[idx]; e=methods[idx+1][2]
    chunk='\n'.join(lines[s:e])
    writes=len(re.findall(r'self\.call\("(?:PUT|POST)"',chunk))
    loops = len(re.findall(r'for .+ in (.+):', chunk))
    if writes: print(f"{cname}.{mname}: direct_calls={writes} loops={loops}")
EOF

